import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"篇892｜超脱者与军事·对比掠夺派的军事扩张","description":"","frontmatter":{"title":"篇892｜超脱者与军事·对比掠夺派的军事扩张","no":892,"module":4,"tags":["超脱","军事","掠夺派","军事扩张","对比批判"],"related":["04-反掠夺主义核心论纲","728-对比掠夺派超脱者的寄生本质","888-超脱者与军事总论","889-非掠夺式安全保障"]},"headers":[],"relativePath":"zh/892_模块4-超脱者与军事-对比掠夺派的军事扩张.md","filePath":"zh/892_模块4-超脱者与军事-对比掠夺派的军事扩张.md"}'),l={name:"zh/892_模块4-超脱者与军事-对比掠夺派的军事扩张.md"};function d(i,t,h,n,s,_){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="篇892-超脱者与军事·对比掠夺派的军事扩张" tabindex="-1">篇892｜超脱者与军事·对比掠夺派的军事扩张 <a class="header-anchor" href="#篇892-超脱者与军事·对比掠夺派的军事扩张" aria-label="Permalink to &quot;篇892｜超脱者与军事·对比掠夺派的军事扩张&quot;">​</a></h1><blockquote><p>所属模块：模块四·超脱正统定义库｜对标地基：文档04、728、888、889</p></blockquote><h2 id="引言-同样是强者-一个修城墙一个拆别人的家" tabindex="-1">引言：同样是强者，一个修城墙一个拆别人的家 <a class="header-anchor" href="#引言-同样是强者-一个修城墙一个拆别人的家" aria-label="Permalink to &quot;引言：同样是强者，一个修城墙一个拆别人的家&quot;">​</a></h2><p>掠夺派强者的军事逻辑和衡元宙超脱者的安全逻辑，表面上都是&quot;用力量保护自己&quot;，本质上完全相反。本篇做一个正面对比，把两种军事哲学的根本差异钉死。</p><p>六大顶层公理在此刻同时压阵：反掠夺主义公理是对比的主轴——掠夺派违反它，共生派遵守它；万族共和公理对比两者对万族的态度；集体升维公理对比两者的终极目标；因果自律公理对比两者的行为可追溯性；法则优先公理对比两者的长期自洽性；众生全员无限均等公理确认所有生灵自带基础无限之力，佛系懒狗保有保底不被淘汰，卷王少年至尊可叠加更高无限——无限本源人人自带，掠夺自然失去意义。</p><p>众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、对比总表" tabindex="-1">一、对比总表 <a class="header-anchor" href="#一、对比总表" aria-label="Permalink to &quot;一、对比总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>掠夺派军事扩张</th><th>共生派防御保障</th></tr></thead><tbody><tr><td>目的</td><td>掠夺资源、消灭对手、建立霸权</td><td>保护万族、维护和平、预防冲突</td></tr><tr><td>手段</td><td>主动进攻、占领、殖民、奴役</td><td>防御、威慑、调解、韧性建设</td></tr><tr><td>能量来源</td><td>掠夺弱者本源</td><td>增量开发、万族共建</td></tr><tr><td>对被征服者</td><td>奴役、剥削、灭族</td><td>（无征服对象）</td></tr><tr><td>对自己人</td><td>内部竞争、强者通吃</td><td>多劳多得、万族共享</td></tr><tr><td>长期结果</td><td>树敌无数、终将被反杀</td><td>朋友越多越安全</td></tr><tr><td>文明方向</td><td>历史倒退</td><td>集体升维</td></tr></tbody></table><h2 id="二、掠夺派军事扩张的三个阶段" tabindex="-1">二、掠夺派军事扩张的三个阶段 <a class="header-anchor" href="#二、掠夺派军事扩张的三个阶段" aria-label="Permalink to &quot;二、掠夺派军事扩张的三个阶段&quot;">​</a></h2><p>掠夺派的军事扩张不是随机的，它有固定模式：</p><h3 id="阶段一-崛起" tabindex="-1">阶段一：崛起 <a class="header-anchor" href="#阶段一-崛起" aria-label="Permalink to &quot;阶段一：崛起&quot;">​</a></h3><p>一个掠夺派强者在某个小范围崛起，通过吞噬弱者变得更强。此时他规模小、影响有限。</p><h3 id="阶段二-扩张" tabindex="-1">阶段二：扩张 <a class="header-anchor" href="#阶段二-扩张" aria-label="Permalink to &quot;阶段二：扩张&quot;">​</a></h3><p>他开始吞并周边文明，每吞并一个就吸收对方的能量和资源，变得更强。吞并的速度越来越快。</p><h3 id="阶段三-崩溃" tabindex="-1">阶段三：崩溃 <a class="header-anchor" href="#阶段三-崩溃" aria-label="Permalink to &quot;阶段三：崩溃&quot;">​</a></h3><p>扩张到极限后，内部矛盾爆发（被征服者反抗、内部竞争者分裂），或者遇到更强的掠夺派把他灭了。掠夺派文明的生命周期，就是从弱到强再到崩溃。</p><p>衡元宙的超脱者做的事，就是在阶段一就识别出这种趋势，在阶段二就通过外交或防御阻止它，绝不让它走到阶段三。</p><h2 id="三、为什么掠夺派军事扩张必然失败" tabindex="-1">三、为什么掠夺派军事扩张必然失败 <a class="header-anchor" href="#三、为什么掠夺派军事扩张必然失败" aria-label="Permalink to &quot;三、为什么掠夺派军事扩张必然失败&quot;">​</a></h2><p>掠夺派的军事扩张看起来不可阻挡，但它有三个致命bug：</p><ol><li><strong>能量来源不可持续</strong>：掠夺来的能量总有尽头——所有弱小文明都被吃完了，掠夺者自己就开始内斗</li><li><strong>敌人越打越多</strong>：每征服一个文明，就多一批仇恨者</li><li><strong>内部不团结</strong>：掠夺派内部也是弱肉强食，强者随时可能被自己人篡位</li></ol><p>这三个bug决定了掠夺派军事扩张是一条不归路——它能赢一时，赢不了永远。</p><h2 id="四、共生派防御为什么可持续" tabindex="-1">四、共生派防御为什么可持续 <a class="header-anchor" href="#四、共生派防御为什么可持续" aria-label="Permalink to &quot;四、共生派防御为什么可持续&quot;">​</a></h2><p>共生派的防御逻辑正好相反：</p><ol><li><strong>能量来源可持续</strong>：增量开发永不枯竭，不需要掠夺</li><li><strong>朋友越交越多</strong>：每和一个文明建立共生关系，就多一个朋友</li><li><strong>内部团结</strong>：万族共和体系内，弱肉强食被禁止，团结是制度性的</li></ol><p>这三个优势决定了共生派的防御是长期的、可持续的——它不靠打赢战争，靠让战争打不起来。</p><p>两种军事哲学的对比，本质上是两种文明观的对比。掠夺派认为文明是抢出来的，共生派认为文明是建出来的。选哪条路，决定了文明的寿命——抢来的文明随掠夺者一起死，建出来的文明随万族一起永续。</p><p>掠夺派的军事扩张还有一个致命问题：它越扩张，管理成本越高。占领一个文明容易，但统治它需要长期驻军、镇压反抗、消化资源——这些成本远超掠夺收益。共生派不需要占领，所以没有这个负担。</p><h2 id="五、五大核心落点" tabindex="-1">五、五大核心落点 <a class="header-anchor" href="#五、五大核心落点" aria-label="Permalink to &quot;五、五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：掠夺派把能量浪费在战争和占领上；共生派把能量用在建设和防御上</li><li><strong>反掠夺</strong>：直接对比两种哲学——掠夺派的军事就是掠夺本身，共生派的军事只用于自卫</li><li><strong>唐罗上限对比</strong>：唐罗是掠夺派军事扩张的终极形态——一人灭世、强者通吃；衡元宙是共生派防御的终极形态——万族共建、防御共生</li><li><strong>万族全覆盖</strong>：共生防御保护万族一切生灵；掠夺扩张奴役一切弱者</li><li><strong>超多元全开放</strong>：共生防御体系全网公开；掠夺派的军事机密在共生体系内不存在</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>掠夺派的军事是扩张——打赢了就占领、奴役、继续扩张，直到崩溃。共生派的军事是防御——守住家门、调解冲突、建设韧性，让战争打不起来。一个是拆别人的家建自己的宫殿，一个是修城墙保护所有人的家。同样是强者，方向完全相反。选哪条路，决定了文明能走多远。这，才是两种军事哲学对比的正统定义。</p><p>说到底，本篇所述的超脱者与军事·对比掠夺派的军事扩张并非孤例——其因果与能级留痕全程纳入阿赖耶网络备案、可溯可校。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./04-反掠夺主义核心论纲.html">04-反掠夺主义核心论纲</a> · <a href="./728_模块4-对比掠夺派超脱者的寄生本质.html">728-对比掠夺派超脱者的寄生本质</a> · <a href="./888_模块4-超脱者与军事-总论.html">888-超脱者与军事总论</a> · <a href="./889_模块4-超脱者与军事-非掠夺式安全保障.html">889-非掠夺式安全保障</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',34)])])}const c=a(l,[["render",d]]);export{u as __pageData,c as default};
